import{_ as e,o as a,c as l,a2 as i}from"./chunks/framework.CFuv5BrO.js";const u=JSON.parse('{"title":"设计原则与架构不变量","description":"Hearth 的五个不可妥协判断、核心设计选择、七条架构不变量与参考系统边界。","frontmatter":{"title":"设计原则与架构不变量","description":"Hearth 的五个不可妥协判断、核心设计选择、七条架构不变量与参考系统边界。","outline":[2,3]},"headers":[],"relativePath":"product/design-principles.md","filePath":"product/design-principles.md","lastUpdated":null}'),n={name:"product/design-principles.md"};function r(o,t,s,d,p,h){return a(),l("div",null,[...t[0]||(t[0]=[i(`<p class="eyebrow">DESIGN PRINCIPLES</p><h1 id="设计原则与架构不变量" tabindex="-1">设计原则与架构不变量 <a class="header-anchor" href="#设计原则与架构不变量" aria-label="Permalink to &quot;设计原则与架构不变量&quot;">​</a></h1><p class="lead">这些判断约束了 Hearth 的产品形态、技术边界和后续所有阶段。它们不是建议，而是不可轻易妥协的设计合同。</p><h2 id="五个不可妥协的判断" tabindex="-1">五个不可妥协的判断 <a class="header-anchor" href="#五个不可妥协的判断" aria-label="Permalink to &quot;五个不可妥协的判断&quot;">​</a></h2><ol><li><strong>价值在控制面、记忆和验证，不在“再实现一个模型”。</strong></li><li><strong>Codex 是强大的并列 Executor，不是产品本体，也不是唯一执行大脑。</strong></li><li><strong>Token 消耗是架构指标；能不用模型的地方，坚决不用模型。</strong></li><li><strong>前端必须简单到用户不需要学习 Agent 架构；复杂逻辑留在后端。</strong></li><li><strong>自进化只能产生候选技能和候选策略，不能绕过权限、评估和人类审查。</strong></li></ol><p>本版追加一条交付判断：</p><ol start="6"><li><strong>先做可每天使用的最小产品，再逐步长成完整 OS；前端从第一个增量开始存在。</strong></li></ol><h2 id="核心设计判断" tabindex="-1">核心设计判断 <a class="header-anchor" href="#核心设计判断" aria-label="Permalink to &quot;核心设计判断&quot;">​</a></h2><h3 id="codex-是并列执行器-不是产品中心" tabindex="-1">Codex 是并列执行器，不是产品中心 <a class="header-anchor" href="#codex-是并列执行器-不是产品中心" aria-label="Permalink to &quot;Codex 是并列执行器，不是产品中心&quot;">​</a></h3><p>Codex 擅长长链路 workspace 工作、代码、测试、Issue/PR、调研、文档、表格和多步骤 Shell；不适合作为长期记忆、权限中心、凭据中心、常驻事件监听器或实时桌面操作器。</p><p>路由原则是：</p><blockquote><p><strong>哪个执行器能以最低 Token、最高可靠性、最小权限完成并通过验证，就选哪个。</strong></p></blockquote><h3 id="自研与集成的边界" tabindex="-1">自研与集成的边界 <a class="header-anchor" href="#自研与集成的边界" aria-label="Permalink to &quot;自研与集成的边界&quot;">​</a></h3><p>Hearth 自研：</p><ul><li>控制面、Durable Harness、Event Log 协议；</li><li>Policy、Mandate、Capability、Approval；</li><li>Context Compiler、Token Governor；</li><li>Memory OS、Evolution OS；</li><li>Execution Gateway 控制逻辑、Credential Broker；</li><li>任务卡、审批、产物和手机入口；</li><li>验证器与评估体系；</li><li>Native Runtime 的薄执行层。</li></ul><p>Hearth 集成：</p><ul><li>模型 API 或本地模型；</li><li>Codex；</li><li>Playwright；</li><li>文档解析/转换库；</li><li>官方邮件、日历、云盘 API/MCP；</li><li>容器/微虚拟机/Sandbox 内核；</li><li>OpenTelemetry。</li></ul><p>Hearth 不重写模型推理引擎、容器/虚拟化内核、完整第三方 Agent 框架或文档解析器。</p><h3 id="前端不是后置包装层" tabindex="-1">前端不是后置包装层 <a class="header-anchor" href="#前端不是后置包装层" aria-label="Permalink to &quot;前端不是后置包装层&quot;">​</a></h3><p>用户打开 Hearth 只需知道三件事：它在做什么、是否需要我、下一步点哪里。</p><ul><li>首页不是无限聊天流，而是任务卡；</li><li>每个状态只有一个主动作；</li><li>审批不藏在多层设置里；</li><li>手机可以完成高风险动作确认；</li><li>技术术语不进入主界面；</li><li>任何异常都有可执行恢复路径；</li><li>只存在于 CLI、日志、数据库或测试中的能力，不计入阶段完成。</li></ul><h3 id="一个逻辑-agent-多设备执行" tabindex="-1">一个逻辑 Agent，多设备执行 <a class="header-anchor" href="#一个逻辑-agent-多设备执行" aria-label="Permalink to &quot;一个逻辑 Agent，多设备执行&quot;">​</a></h3><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>一个逻辑 Hearth</span></span>
<span class="line"><span>  ├─ 一个主 Gateway / Control Plane</span></span>
<span class="line"><span>  ├─ 一个 Event Log / 单写者</span></span>
<span class="line"><span>  ├─ 多台设备上的 agentd</span></span>
<span class="line"><span>  ├─ 手机作为查看、审批、接管、发起入口</span></span>
<span class="line"><span>  └─ 每个设备注册自己的能力</span></span></code></pre></div><p>设备只提供执行能力和入口，不复制身份、事实源和授权。</p><h3 id="学习-openclaw-与-hermes-但不复制它们" tabindex="-1">学习 OpenClaw 与 Hermes，但不复制它们 <a class="header-anchor" href="#学习-openclaw-与-hermes-但不复制它们" aria-label="Permalink to &quot;学习 OpenClaw 与 Hermes，但不复制它们&quot;">​</a></h3><p>OpenClaw 值得学习 Gateway、渠道、设备节点、常驻、自主分级和注意力入口；Hermes 值得学习记忆预算、记忆约束、技能沉淀、子任务生命周期和进化闭环。</p><p>不 fork、不作为运行时依赖、不让参考项目变成产品底座。Hearth 只吸收模式，并通过自己的 Event Log、Policy、Memory 和 Evolution 协议实现。</p><h2 id="七条架构不变量" tabindex="-1">七条架构不变量 <a class="header-anchor" href="#七条架构不变量" aria-label="Permalink to &quot;七条架构不变量&quot;">​</a></h2><ol><li>Event Log 是唯一事实源。</li><li>每个 State Root 只有一个写权威。</li><li>所有外部副作用必须有幂等键、审批或明确豁免、以及 Receipt。</li><li>执行器不能直接读取长期原始凭据。</li><li>每个任务必须有预算、截止时间和取消路径。</li><li>记忆必须有 provenance、敏感度、冲突和遗忘策略。</li><li>任何自进化都必须经过评估、canary 和回滚。</li></ol><p>再加一条交付不变量：</p><ol start="8"><li><strong>每个增量都必须是可用纵向切片：用户结果、界面、持久状态、真实执行、验证、恢复和度量同时出现。</strong></li></ol><h2 id="参考系统的位置" tabindex="-1">参考系统的位置 <a class="header-anchor" href="#参考系统的位置" aria-label="Permalink to &quot;参考系统的位置&quot;">​</a></h2><table tabindex="0"><thead><tr><th>参考</th><th>学习什么</th><th>不做什么</th></tr></thead><tbody><tr><td>OpenClaw</td><td>Gateway、渠道、设备、注意力、常驻</td><td>不 fork、不复制渠道规模</td></tr><tr><td>Hermes</td><td>记忆预算、技能、生命周期、进化</td><td>不做无界自修改</td></tr><tr><td>DeerFlow</td><td>Harness/App 分层、Run 生命周期</td><td>不引入重型框架耦合</td></tr><tr><td>Pi / Maka</td><td>session tree、steering、compaction</td><td>不复制完整框架</td></tr><tr><td>OpenSandbox / OpenBot</td><td>隔离、快照、takeover、receipt</td><td>不复制完整产品</td></tr><tr><td>OpenMuse / OpenDots</td><td>durable job、checkpoint、lease</td><td>不照搬任务模型</td></tr><tr><td>Codex</td><td>工作区执行、代码、研究、文档</td><td>不当权限中心或记忆中心</td></tr></tbody></table><h2 id="本章结论" tabindex="-1">本章结论 <a class="header-anchor" href="#本章结论" aria-label="Permalink to &quot;本章结论&quot;">​</a></h2><p>Hearth 的护城河不是“拥有一个更强的模型”，而是知道什么时候不该调用模型、该给执行器什么最小上下文、哪些动作需要谁的授权、如何证明任务真的完成、失败后如何恢复、什么该记住、什么该遗忘。</p><p>但这一切必须先以一个真实可用的最小产品出现，而不是等架构全部完成后才让用户看到。</p>`,36)])])}const b=e(n,[["render",r]]);export{u as __pageData,b as default};
